CHURCH_TRAP_SCREEN_Y EQU 6
CHURCH_TRAP_CELL_LO_X EQU 15
CHURCH_TRAP_CELL_HI_X EQU 16
CHURCH_TRAP_CELL_Y    EQU 12
CHURCH_KEY_ALT1_SCREEN_X EQU 15
CHURCH_KEY_ALT1_SCREEN_Y EQU 6
